import pandas as pd

def run(inputs: dict) -> dict:
    target = inputs["target_snapshot"].copy()
    cdc = inputs["cdc_events"].copy()

    # Build watermark map: device_id -> applied_event_ts (from target)
    watermark = dict(zip(target["device_id"], target["applied_event_ts"]))

    # Determine which cdc events survive the per-device watermark check
    def survives(row):
        dev = row["device_id"]
        wm = watermark.get(dev, None)
        if wm is None:
            return True
        return row["event_ts"] > wm

    if len(cdc) > 0:
        mask = cdc.apply(survives, axis=1)
        surviving = cdc[mask].copy()
    else:
        surviving = cdc.copy()

    # Among surviving events per device, pick the one with max (event_ts, event_seq)
    winners = {}
    if len(surviving) > 0:
        surviving_sorted = surviving.sort_values(
            by=["event_ts", "event_seq"], ascending=[True, True]
        )
        # group by device_id, take last (max) row per group
        grouped = surviving_sorted.groupby("device_id", sort=False)
        for dev, grp in grouped:
            last_row = grp.iloc[-1]
            winners[dev] = (last_row["reading"], last_row["event_ts"])

    # Start building result rows
    result_rows = []

    # Devices present in target: carry forward or update
    target_devices = set(target["device_id"])
    for _, row in target.iterrows():
        dev = row["device_id"]
        if dev in winners:
            reading, applied_ts = winners[dev]
            result_rows.append({
                "device_id": dev,
                "reading": reading,
                "applied_event_ts": applied_ts
            })
        else:
            result_rows.append({
                "device_id": dev,
                "reading": row["reading"],
                "applied_event_ts": row["applied_event_ts"]
            })

    # New devices: present in winners but not in target
    for dev, (reading, applied_ts) in winners.items():
        if dev not in target_devices:
            result_rows.append({
                "device_id": dev,
                "reading": reading,
                "applied_event_ts": applied_ts
            })

    new_snapshot = pd.DataFrame(
        result_rows,
        columns=["device_id", "reading", "applied_event_ts"]
    )

    # Ensure dtypes match expected output
    if len(new_snapshot) > 0:
        new_snapshot["device_id"] = new_snapshot["device_id"].astype("int64")
        new_snapshot["reading"] = new_snapshot["reading"].astype("float64")
        new_snapshot["applied_event_ts"] = pd.to_datetime(new_snapshot["applied_event_ts"]).astype("datetime64[us]")
    else:
        new_snapshot = pd.DataFrame({
            "device_id": pd.Series(dtype="int64"),
            "reading": pd.Series(dtype="float64"),
            "applied_event_ts": pd.Series(dtype="datetime64[us]")
        })

    return {"new_snapshot": new_snapshot}
